import React from 'react';
import { SLAAlertFilters, SLASeverity } from '../../../models/SLAAlert';
import './AlertsFilters.css';

interface AlertsFiltersProps {
  filters: SLAAlertFilters;
  onFiltersChange: (filters: SLAAlertFilters) => void;
}

export const AlertsFilters: React.FC<AlertsFiltersProps> = ({ filters, onFiltersChange }) => {
  const handleSeverityChange = (severity: SLAAlertFilters['severity']) => {
    onFiltersChange({ ...filters, severity });
  };

  const handleTypeChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    onFiltersChange({ ...filters, type: e.target.value as SLAAlertFilters['type'] });
  };

  const handleDepartmentChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    onFiltersChange({ ...filters, departmentId: e.target.value });
  };

  const handleClearFilters = () => {
    onFiltersChange({
      severity: 'all',
      type: 'all',
      departmentId: 'all',
    });
  };

  const hasActiveFilters =
    filters.severity !== 'all' ||
    filters.type !== 'all' ||
    filters.departmentId !== 'all';

  return (
    <div className="alerts-filters">
      <div className="alerts-filters__group">
        <label className="alerts-filters__label">Mức độ nghiêm trọng:</label>
        <div className="alerts-filters__severity-buttons">
          <button
            className={`alerts-filters__severity-btn ${
              filters.severity === 'all' ? 'alerts-filters__severity-btn--active' : ''
            }`}
            onClick={() => handleSeverityChange('all')}
          >
            Tất cả
          </button>
          <button
            className={`alerts-filters__severity-btn alerts-filters__severity-btn--breached ${
              filters.severity === SLASeverity.Breached ? 'alerts-filters__severity-btn--active' : ''
            }`}
            onClick={() => handleSeverityChange(SLASeverity.Breached)}
          >
            Vi phạm
          </button>
          <button
            className={`alerts-filters__severity-btn alerts-filters__severity-btn--danger ${
              filters.severity === SLASeverity.Danger ? 'alerts-filters__severity-btn--active' : ''
            }`}
            onClick={() => handleSeverityChange(SLASeverity.Danger)}
          >
            Nguy cơ cao
          </button>
          <button
            className={`alerts-filters__severity-btn alerts-filters__severity-btn--warning ${
              filters.severity === SLASeverity.Warning ? 'alerts-filters__severity-btn--active' : ''
            }`}
            onClick={() => handleSeverityChange(SLASeverity.Warning)}
          >
            Cảnh báo
          </button>
          <button
            className={`alerts-filters__severity-btn alerts-filters__severity-btn--watch ${
              filters.severity === SLASeverity.Watch ? 'alerts-filters__severity-btn--active' : ''
            }`}
            onClick={() => handleSeverityChange(SLASeverity.Watch)}
          >
            Theo dõi
          </button>
        </div>
      </div>

      <div className="alerts-filters__group">
        <label className="alerts-filters__label" htmlFor="type-filter">
          Loại:
        </label>
        <select
          id="type-filter"
          className="alerts-filters__select"
          value={filters.type}
          onChange={handleTypeChange}
        >
          <option value="all">Tất cả</option>
          <option value="ticket">Phiếu yêu cầu</option>
          <option value="task">Công việc</option>
        </select>
      </div>

      <div className="alerts-filters__group">
        <label className="alerts-filters__label" htmlFor="department-filter">
          Khoa/Phòng:
        </label>
        <select
          id="department-filter"
          className="alerts-filters__select"
          value={filters.departmentId}
          onChange={handleDepartmentChange}
        >
          <option value="all">Tất cả</option>
          <option value="dept-khoa-noi">Khoa Nội</option>
          <option value="dept-khoa-ngoai">Khoa Ngoại</option>
          <option value="dept-khoa-san">Khoa Sản</option>
          <option value="dept-kham-benh">Khám Bệnh</option>
          <option value="dept-cdha">CĐHA</option>
          <option value="dept-xn">Xét Nghiệm</option>
          <option value="dept-it">CNTT</option>
        </select>
      </div>

      {hasActiveFilters && (
        <button className="alerts-filters__clear-btn" onClick={handleClearFilters}>
          Xóa bộ lọc
        </button>
      )}
    </div>
  );
};
