import {
  HistoryItem,
  HistoryStats,
  HistoryFilters,
  HistoryExportOptions,
} from '../models/History';
import { mockHistoryItems, mockHistoryStats, filterHistoryItems } from '../mocks/history.mock';
import { USE_MOCK_DATA } from '@/config/appSettings';

/**
 * History Service
 * Handles API calls for work history and activity tracking
 */


/**
 * Simulate network delay for more realistic mock behavior
 */
const mockDelay = (ms = 500): Promise<void> => {
  return new Promise((resolve) => setTimeout(resolve, ms));
};

class HistoryService {
  /**
   * Get user's work history with optional filters
   */
  async getHistory(filters?: HistoryFilters): Promise<HistoryItem[]> {
    if (USE_MOCK_DATA) {
      await mockDelay();
      
      let items = [...mockHistoryItems];

      // Apply filters
      if (filters?.search) {
        items = filterHistoryItems(items, filters.search);
      }

      if (filters?.type) {
        items = filterHistoryItems(items, undefined, filters.type);
      }

      if (filters?.priority) {
        items = filterHistoryItems(items, undefined, undefined, filters.priority);
      }

      if (filters?.dateRange) {
        items = items.filter((item) => {
          const itemDate = new Date(item.completedAt || item.createdAt);
          return (
            itemDate >= filters.dateRange!.from &&
            itemDate <= filters.dateRange!.to
          );
        });
      }

      // Sort by completion date (most recent first)
      items.sort((a, b) => {
        const dateA = new Date(a.completedAt || a.createdAt).getTime();
        const dateB = new Date(b.completedAt || b.createdAt).getTime();
        return dateB - dateA;
      });

      return items;
    }

    // TODO: Replace with real API call when backend is ready
    // const response = await apiClient.get<HistoryItem[]>('/api/history/me', {
    //   params: filters,
    // });
    // return response;
    
    return [];
  }

  /**
   * Get history statistics summary
   */
  async getStats(): Promise<HistoryStats> {
    if (USE_MOCK_DATA) {
      await mockDelay(300);
      return mockHistoryStats;
    }

    // TODO: Replace with real API call
    // return await apiClient.get<HistoryStats>('/api/history/stats');
    
    return {
      totalCompleted: 0,
      completedThisMonth: 0,
      completedThisWeek: 0,
      totalTimeSpent: 0,
      averageRating: 0,
      onTimePercentage: 0,
      slaBreaches: 0,
    };
  }

  /**
   * Export history report
   */
  async exportReport(options: HistoryExportOptions): Promise<Blob> {
    if (USE_MOCK_DATA) {
      await mockDelay(1000);
      
      // Generate mock CSV data
      if (options.format === 'csv') {
        const items = await this.getHistory({ dateRange: options.dateRange });
        const csvContent = this.generateCSV(items);
        return new Blob([csvContent], { type: 'text/csv' });
      }
      
      // For PDF, return a mock blob
      return new Blob(['Mock PDF content'], { type: 'application/pdf' });
    }

    // TODO: Replace with real API call
    // const response = await apiClient.post<Blob>('/api/history/export', options, {
    //   responseType: 'blob',
    // });
    // return response;
    
    return new Blob();
  }

  /**
   * Get a single history item by ID
   */
  async getHistoryItem(id: string): Promise<HistoryItem | null> {
    if (USE_MOCK_DATA) {
      await mockDelay(200);
      return mockHistoryItems.find((item) => item.id === id) || null;
    }

    // TODO: Replace with real API call
    // return await apiClient.get<HistoryItem>(`/api/history/items/${id}`);
    
    return null;
  }

  /**
   * Generate CSV content from history items
   */
  private generateCSV(items: HistoryItem[]): string {
    const headers = [
      'Mã',
      'Loại',
      'Tiêu đề',
      'Hành động',
      'Ưu tiên',
      'Trạng thái',
      'Thời gian hoàn thành',
      'Thời gian thực hiện (giờ)',
      'Thời gian ước tính (giờ)',
      'Đánh giá',
      'SLA',
    ];

    const rows = items.map((item) => [
      item.entityCode,
      item.type === 'ticket' ? 'Phiếu' : 'Công việc',
      item.entityTitle,
      item.actionDescription,
      item.priority,
      item.status,
      item.completedAt ? new Date(item.completedAt).toLocaleString('vi-VN') : '',
      item.timeSpent?.toString() || '',
      item.estimatedTime?.toString() || '',
      item.rating?.toString() || '',
      item.slaStatus || '',
    ]);

    const csvRows = [headers, ...rows];
    return csvRows.map((row) => row.join(',')).join('\n');
  }
}

export const historyService = new HistoryService();
