import React, { useState } from 'react';
import { Slideout } from '../../../components/common/Slideout';
import { TextArea } from '../../../components/common/TextArea';
import styles from './WorkflowModal.module.css';

interface MarkBlockedModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSubmit: (reason: string) => Promise<void>;
  taskTitle: string;
}

export const MarkBlockedModal: React.FC<MarkBlockedModalProps> = ({
  isOpen,
  onClose,
  onSubmit,
  taskTitle,
}) => {
  const [reason, setReason] = useState('');
  const [submitting, setSubmitting] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!reason.trim()) return;

    setSubmitting(true);
    try {
      await onSubmit(reason.trim());
      handleClose();
    } catch (error) {
      console.error('Failed to mark blocked:', error);
    } finally {
      setSubmitting(false);
    }
  };

  const handleClose = () => {
    setReason('');
    onClose();
  };

  const handleConfirmSubmit = () => {
    handleSubmit(new Event('submit') as any);
  };

  return (
    <Slideout 
      isOpen={isOpen} 
      onClose={handleClose} 
      title="Đánh dấu task bị block"
      width="500px"
      footer={{
        leftLabel: 'Hủy',
        leftAction: handleClose,
        leftDisabled: submitting,
        rightLabel: submitting ? 'Đang xử lý...' : 'Đánh dấu bị block',
        rightAction: handleConfirmSubmit,
        rightDisabled: !reason.trim() || submitting,
      }}
    >
      <form className={styles.form}>
        <div className={styles.taskInfo}>
          <span className={styles.label}>Task:</span>
          <span className={styles.value}>{taskTitle}</span>
        </div>

        <div className={styles.alert}>
          <i className="fas fa-exclamation-triangle"></i>
          <span>Task sẽ được đánh dấu là bị block và tạm dừng tiến độ</span>
        </div>

        <div className={styles.formGroup}>
          <label htmlFor="reason" className={styles.label}>
            Lý do bị block <span className={styles.required}>*</span>
          </label>
          <TextArea
            id="reason"
            value={reason}
            onChange={(e) => setReason(e.target.value)}
            placeholder="Ví dụ: Đang chờ task #123 hoàn thành, cần thông tin từ khách hàng, thiếu tài nguyên..."
            rows={4}
            required
            disabled={submitting}
          />
          <span className={styles.hint}>
            Mô tả rõ nguyên nhân block để team có thể hỗ trợ giải quyết
          </span>
        </div>
      </form>
    </Slideout>
  );
};
