  /**
   * Search help articles
   */
  async search(query: string): Promise<HelpSearchResult[]> {
    if (USE_MOCK_DATA) {
      await mockDelay(300);
      
      if (!query || query.length < 2) {
        return [];
      }

      const queryLower = query.toLowerCase();
      const results: HelpSearchResult[] = [];

      // Search articles
      mockHelpArticles.forEach(article => {
        if (
          article.title.toLowerCase().includes(queryLower) ||
          article.description.toLowerCase().includes(queryLower) ||
          article.tags.some(tag => tag.toLowerCase().includes(queryLower))
        ) {
          results.push({
            type: 'article',
            id: article.id,
            title: article.title,
            description: article.description,
            category: article.category,
            url: `/help/articles/${article.slug}`,
          });
        }
      });

      // Search FAQs
      mockFAQs.forEach(faq => {
        if (
          faq.question.toLowerCase().includes(queryLower) ||
          faq.answer.toLowerCase().includes(queryLower)
        ) {
          results.push({
            type: 'faq',
            id: faq.id,
            title: faq.question,
            description: faq.answer.substring(0, 100) + '...',
            category: faq.category,
            url: `/help/faq#${faq.id}`,
          });
        }
      });

      return results.slice(0, 5); // Return top 5 results
    }

    // TODO: Replace with real API call
    // return await apiClient.get<HelpSearchResult[]>('/api/help/search', { params: { q: query } });
    
    return [];
  }

