import React, { useState, useMemo } from 'react';
import { Select, SelectOption } from '../../../../components/common/Select';
import { TicketPriority, TicketStatus, TicketFilters as ITicketFilters } from '../../../../models/Ticket';
import { useResponsive } from '../../../../hooks/useResponsive';
import styles from './TicketFilters.module.css';

export interface TicketFiltersProps {
  filters: ITicketFilters;
  onChange: (filters: ITicketFilters) => void;
}

const scopeOptions: SelectOption[] = [
  { value: 'my', label: 'Phiếu của tôi' },
  { value: 'all', label: 'Tất cả phiếu' },
  { value: 'team', label: 'Phiếu nhóm' },
];

const priorityOptions: SelectOption[] = [
  { value: '', label: 'Tất cả ưu tiên' },
  { value: TicketPriority.Emergency, label: 'Khẩn cấp' },
  { value: TicketPriority.High, label: 'Cao' },
  { value: TicketPriority.Medium, label: 'Trung bình' },
  { value: TicketPriority.Low, label: 'Thấp' },
];

const statusOptions: SelectOption[] = [
  { value: '', label: 'Tất cả trạng thái' },
  { value: TicketStatus.New, label: 'MỚI TẠO' },
  { value: 'submitted', label: 'ĐANG XEM XÉT' },
  { value: 'assigned', label: 'Đã phân công' },
  { value: TicketStatus.InProgress, label: 'Đang xử lý' },
  { value: TicketStatus.Resolved, label: 'ĐÃ XỬ LÝ' },
  { value: TicketStatus.Closed, label: 'CLOSED' },
];

export const TicketFilters: React.FC<TicketFiltersProps> = ({ filters, onChange }) => {
  const { isMobile } = useResponsive();
  const [isExpanded, setIsExpanded] = useState(false);

  // Count active filters (excluding scope which is always set)
  const activeFilterCount = useMemo(() => {
    let count = 0;
    if (filters.priority) count++;
    if (filters.status) count++;
    return count;
  }, [filters]);

  const handleScopeChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    onChange({
      ...filters,
      scope: e.target.value as ITicketFilters['scope'],
    });
  };

  const handlePriorityChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    onChange({
      ...filters,
      priority: e.target.value ? (e.target.value as TicketPriority) : undefined,
    });
  };

  const handleStatusChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    onChange({
      ...filters,
      status: e.target.value ? (e.target.value as TicketStatus) : undefined,
    });
  };

  const handleToggle = () => {
    setIsExpanded(!isExpanded);
  };

  const handleClose = () => {
    setIsExpanded(false);
  };

  const handleClearFilters = () => {
    onChange({
      scope: 'my',
      priority: undefined,
      status: undefined,
    });
  };

  // Check if any filters are active (excluding scope)
  const hasActiveFilters = useMemo(() => {
    return !!(filters.priority || filters.status);
  }, [filters]);

  // Mobile: Collapsible UI
  if (isMobile) {
    return (
      <>
        {/* Backdrop - click to close */}
        {isExpanded && (
          <div className={styles.filterBackdrop} onClick={handleClose} />
        )}

        <div className={styles.container}>
          <div className={styles.mobileHeader}>
            <div className={styles.title}>Danh Sách Phiếu Yêu Cầu</div>
            
            <div className={styles.filterDropdownWrapper}>
              <button
                className={styles.filterToggle}
                onClick={handleToggle}
                aria-expanded={isExpanded}
                aria-label="Toggle filters"
              >
                <i className="fas fa-filter"></i>
                <span>Lọc</span>
                {activeFilterCount > 0 && (
                  <span className={styles.filterBadge}>{activeFilterCount}</span>
                )}
                <i className={`fas fa-chevron-${isExpanded ? 'up' : 'down'}`}></i>
              </button>

              {isExpanded && (
                <div className={styles.mobileFilters}>
                  <Select
                    value={filters.scope || 'my'}
                    onChange={handleScopeChange}
                    options={scopeOptions}
                    size="small"
                    fullWidth
                  />

                  <Select
                    value={filters.priority || ''}
                    onChange={handlePriorityChange}
                    options={priorityOptions}
                    size="small"
                    fullWidth
                  />

                  <Select
                    value={filters.status || ''}
                    onChange={handleStatusChange}
                    options={statusOptions}
                    size="small"
                    fullWidth
                  />

                  {/* Clear Filters Button */}
                  {hasActiveFilters && (
                    <button
                      className={styles.clearFiltersButton}
                      onClick={handleClearFilters}
                      type="button"
                    >
                      <i className="fas fa-times-circle"></i>
                      <span>Xóa bộ lọc</span>
                    </button>
                  )}
                </div>
              )}
            </div>
          </div>
        </div>
      </>
    );
  }

  // Desktop: Original horizontal layout
  return (
    <div className={styles.container}>
      <div className={styles.title}>Danh Sách Phiếu Yêu Cầu</div>
      
      <div className={styles.filters}>
        <Select
          value={filters.scope || 'my'}
          onChange={handleScopeChange}
          options={scopeOptions}
          size="small"
        />

        <Select
          value={filters.priority || ''}
          onChange={handlePriorityChange}
          options={priorityOptions}
          size="small"
        />

        <Select
          value={filters.status || ''}
          onChange={handleStatusChange}
          options={statusOptions}
          size="small"
        />

        {/* Clear Filters Button - Desktop */}
        {hasActiveFilters && (
          <button
            className={styles.clearFiltersButtonDesktop}
            onClick={handleClearFilters}
            type="button"
            title="Xóa bộ lọc"
          >
            <i className="fas fa-times-circle"></i>
            <span>Xóa bộ lọc</span>
          </button>
        )}
      </div>
    </div>
  );
};
