import React from 'react';
import styles from './StatCard.module.css';
import { Card } from '../../common/Card';

export interface StatCardProps {
  icon: string;
  iconVariant: 'primary' | 'success' | 'warning' | 'danger' | 'info';
  label: string;
  value: string | number;
  change?: {
    text: string;
    positive?: boolean;
  };
}

export const StatCard: React.FC<StatCardProps> = ({
  icon,
  iconVariant,
  label,
  value,
  change,
}) => {
  return (
    <Card className={styles.statCard}>
      <div className={`${styles.icon} ${styles[iconVariant]}`}>
        <i className={icon}></i>
      </div>
      <div className={styles.content}>
        <div className={styles.label}>{label}</div>
        <div className={styles.value}>{value}</div>
        {change && (
          <div
            className={`${styles.change} ${
              change.positive ? styles.positive : styles.negative
            }`}
          >
            {change.positive && <i className="fas fa-arrow-up"></i>}
            {change.positive === false && <i className="fas fa-arrow-down"></i>}
            {change.text}
          </div>
        )}
      </div>
    </Card>
  );
};
