/**
 * App Settings - Centralized configuration
 *
 * Priority for mock data:
 * 1. VITE_USE_MOCK=true/false  → explicit override (highest priority)
 * 2. VITE_API_URL not set      → auto-enable mock
 * 3. Production env            → always use real API (mock = false)
 */

const apiUrl = import.meta.env.VITE_API_URL as string | undefined;
const explicitMock = import.meta.env.VITE_USE_MOCK as string | undefined;

// Resolve USE_MOCK_DATA:
// - Explicit env var wins if set
// - Otherwise: mock if no API URL is configured
const resolveMock = (): boolean => {
    return true;
  if (explicitMock === 'true') return true;
  if (explicitMock === 'false') return false;
  return !apiUrl; // no API URL → use mock
};

export const appSettings = {
  /** API base URL */
  apiUrl: apiUrl || 'http://localhost:5000/api',

  /** App name */
  appName: (import.meta.env.VITE_APP_NAME as string) || 'QLCV Y Khoa',

  /** Whether to use mock data instead of real API */
  useMockData: resolveMock(),

  /** Enable analytics */
  enableAnalytics: import.meta.env.VITE_ENABLE_ANALYTICS === 'true',

  /** Is production environment */
  isProduction: import.meta.env.PROD,

  /** Is development environment */
  isDev: import.meta.env.DEV,
} as const;

// Dev logging
if (import.meta.env.DEV) {
  console.log('⚙️ App Settings:', {
    apiUrl: appSettings.apiUrl,
    useMockData: appSettings.useMockData,
    environment: appSettings.isProduction ? 'Production' : 'Development',
  });
}

/** Shorthand export used across all services */
export const USE_MOCK_DATA = appSettings.useMockData;
