import React from 'react';
import { useNavigate } from 'react-router-dom';
import { HelpCategoryInfo } from '../../../models/Help';
import styles from './CategoryGrid.module.css';

interface CategoryGridProps {
  categories: HelpCategoryInfo[];
}

export const CategoryGrid: React.FC<CategoryGridProps> = ({ categories }) => {
  const navigate = useNavigate();

  const handleCategoryClick = (categoryId: string) => {
    navigate(`/help/category/${categoryId}`);
  };

  return (
    <div className={styles.grid}>
      {categories.map((category) => (
        <button
          key={category.id}
          className={styles.card}
          onClick={() => handleCategoryClick(category.id)}
        >
          <i className={`${category.icon} ${styles.icon}`} />
          <h3 className={styles.title}>{category.label}</h3>
          <p className={styles.description}>{category.description}</p>
          <span className={styles.count}>
            {category.articleCount} bài viết
          </span>
        </button>
      ))}
    </div>
  );
};
