import React, { useState, useMemo } from 'react';
import { Ticket } from '../../../models/Ticket';
import { Card, Tabs, Tab } from '../../../components/common';
import { ChatTab, ChatMessage, CommentsTab, ActivityTab, AttachmentsTab } from '../../../components/shared';
import styles from './TicketTabs.module.css';

interface TicketTabsProps {
  ticket: Ticket;
}

type TabType = 'chat' | 'comments' | 'activity' | 'attachments';

const TicketTabs: React.FC<TicketTabsProps> = ({ ticket }) => {
  const [activeTab, setActiveTab] = useState<TabType>('chat');

  // Mock chat messages for ticket
  const mockChatMessages: ChatMessage[] = [
    {
      id: 'chat-1',
      entityId: ticket.id,
      userId: 'user-001',
      userName: 'Linh Dinh',
      userAvatar: 'LD',
      message: 'Đã kiểm tra máy in, có thể là do hết mực hoặc bị kẹt giấy.',
      timestamp: new Date(Date.now() - 90 * 60 * 1000).toISOString(), // 1.5 hours ago
    },
    {
      id: 'chat-2',
      entityId: ticket.id,
      userId: 'user-002',
      userName: 'Nguyễn Văn A',
      userAvatar: 'NA',
      message: 'Đã mở nắp máy in, không thấy kẹt giấy. Mực còn 30%.',
      timestamp: new Date(Date.now() - 85 * 60 * 1000).toISOString(), // 1h25m ago
    },
    {
      id: 'chat-3',
      entityId: ticket.id,
      userId: 'user-001',
      userName: 'Linh Dinh',
      userAvatar: 'LD',
      message: 'OK, tôi sẽ đến kiểm tra ngay. Có thể là lỗi driver.',
      timestamp: new Date(Date.now() - 80 * 60 * 1000).toISOString(), // 1h20m ago
    },
  ];

  // Define tabs configuration with overflow detection support
  const tabs: Tab[] = useMemo(
    () => [
      {
        id: 'chat',
        label: 'Trao đổi',
        icon: 'fas fa-comments',
        badge: 3,
        badgeColor: 'primary' as const,
      },
      {
        id: 'comments',
        label: 'Bình luận',
        icon: 'fas fa-comment-dots',
        badge: ticket.commentCount || 0,
        badgeColor: 'gray' as const,
      },
      {
        id: 'activity',
        label: 'Lịch sử',
        icon: 'fas fa-history',
      },
      {
        id: 'attachments',
        label: 'Tệp đính kèm',
        icon: 'fas fa-paperclip',
        badge: ticket.attachmentCount || 0,
        badgeColor: 'gray' as const,
      },
    ],
    [ticket.commentCount, ticket.attachmentCount]
  );

  const renderTabContent = () => {
    switch (activeTab) {
      case 'chat':
        return (
          <ChatTab
            entityId={ticket.id}
            entityType="ticket"
            messages={mockChatMessages}
            onSendMessage={async (message) => {
              console.log('Send ticket chat message:', message);
              // TODO: Call API to send message
            }}
          />
        );
      case 'comments':
        return (
          <CommentsTab
            entityId={ticket.id}
            entityType="ticket"
            comments={[]}
            onAddComment={async (content, parentId) => {
              console.log('Add ticket comment:', content, parentId);
              // TODO: Call API to add comment
            }}
          />
        );
      case 'activity':
        return (
          <ActivityTab
            entityId={ticket.id}
            entityType="ticket"
            activities={[]}
          />
        );
      case 'attachments':
        return (
          <AttachmentsTab
            entityId={ticket.id}
            entityType="ticket"
            attachments={[]}
            onUpload={async (files) => {
              console.log('Upload ticket files:', files);
              // TODO: Call API to upload files
            }}
          />
        );
      default:
        return null;
    }
  };

  return (
    <Card>
      <div className={styles.tabsHeader}>
        <Tabs
          tabs={tabs}
          activeTab={activeTab}
          onTabChange={(tabId) => setActiveTab(tabId as TabType)}
          variant="underline"
        />
      </div>
      <div className={styles.tabContent}>{renderTabContent()}</div>
    </Card>
  );
};

export default TicketTabs;
