/**
 * HistoryFilters Component
 * Filter controls for history items
 */

import React from 'react';
import { HistoryItemType } from '../../../models/History';
import { TicketPriority } from '../../../models/Ticket';
import { TaskPriority } from '../../../models/Task';
import styles from './HistoryFilters.module.css';

interface HistoryFiltersProps {
  search: string;
  onSearchChange: (value: string) => void;
  dateRange: string;
  onDateRangeChange: (value: string) => void;
  itemType: HistoryItemType | '';
  onItemTypeChange: (value: HistoryItemType | '') => void;
  priority: TicketPriority | TaskPriority | '';
  onPriorityChange: (value: TicketPriority | TaskPriority | '') => void;
}

export const HistoryFilters: React.FC<HistoryFiltersProps> = ({
  search,
  onSearchChange,
  dateRange,
  onDateRangeChange,
  itemType,
  onItemTypeChange,
  priority,
  onPriorityChange,
}) => {
  return (
    <div className={styles.filtersCard}>
      <div className={styles.filtersGrid}>
        {/* Search */}
        <div className={styles.searchBox}>
          <i className="fas fa-search"></i>
          <input
            type="text"
            placeholder="Tìm kiếm theo tên, mã công việc..."
            value={search}
            onChange={(e) => onSearchChange(e.target.value)}
          />
        </div>

        {/* Date Range */}
        <select
          className={styles.filterSelect}
          value={dateRange}
          onChange={(e) => onDateRangeChange(e.target.value)}
        >
          <option value="all">Tất cả thời gian</option>
          <option value="today">Hôm nay</option>
          <option value="week">Tuần này</option>
          <option value="month">Tháng này</option>
          <option value="quarter">Quý này</option>
          <option value="year">Năm nay</option>
        </select>

        {/* Item Type */}
        <select
          className={styles.filterSelect}
          value={itemType}
          onChange={(e) => onItemTypeChange(e.target.value as HistoryItemType | '')}
        >
          <option value="">Tất cả loại</option>
          <option value={HistoryItemType.Ticket}>Phiếu yêu cầu</option>
          <option value={HistoryItemType.Task}>Công việc</option>
        </select>

        {/* Priority */}
        <select
          className={styles.filterSelect}
          value={priority}
          onChange={(e) => onPriorityChange(e.target.value as TicketPriority | TaskPriority | '')}
        >
          <option value="">Tất cả ưu tiên</option>
          <option value="critical">Khẩn cấp</option>
          <option value="high">Cao</option>
          <option value="medium">Trung bình</option>
          <option value="low">Thấp</option>
        </select>
      </div>
    </div>
  );
};
