import React, { useEffect } from 'react';
import { useAppDispatch, useAppSelector } from '../../store/hooks';
import { useAlert } from '../../components/common/Alert';
import {
  fetchAllManagerDashboardData,
  reassignSLAAlert,
  approveTask,
  rejectTask,
} from '../../store/slices/managerDashboardSlice';
import styles from './DashboardManagerPage.module.css';
import { StatCard } from '../../components/dashboard/StatCard';
import { TeamWorkload } from '../../components/dashboard/TeamWorkload';
import { SLABreachAlerts } from '../../components/dashboard/SLABreachAlerts';
import { PendingApprovals } from '../../components/dashboard/PendingApprovals';
import { PerformanceCharts } from '../../components/dashboard/PerformanceCharts';

const DashboardManagerPage: React.FC = () => {
  const alert = useAlert();
  const dispatch = useAppDispatch();
  const {
    stats,
    teamWorkload,
    slaBreachAlerts,
    pendingApprovals,
    performanceTrend,
    priorityDistribution,
    loading,
  } = useAppSelector((state) => state.managerDashboard);

  // Fetch initial dashboard data
  useEffect(() => {
    dispatch(fetchAllManagerDashboardData());
  }, [dispatch]);

  // TODO: MQTT Real-time Updates Integration (Phase 3)
  // When MQTT backend is ready, uncomment and implement:
  /*
  useEffect(() => {
    // Import mqttService
    // import { mqttService } from '../../services/mqttService';
    
    // Subscribe to dashboard updates
    const unsubscribeStats = mqttService.subscribe('dashboard/manager/stats', (message) => {
      dispatch(updateManagerStats(message));
    });
    
    const unsubscribeSLA = mqttService.subscribe('dashboard/manager/sla', (message) => {
      dispatch(addSLAAlert(message));
    });
    
    const unsubscribeApprovals = mqttService.subscribe('dashboard/manager/approvals', (message) => {
      // Handle approval updates
      dispatch(fetchPendingApprovals());
    });
    
    // Cleanup subscriptions
    return () => {
      unsubscribeStats();
      unsubscribeSLA();
      unsubscribeApprovals();
    };
  }, [dispatch]);
  */

  // Handlers for SLA alerts
  const handleReassign = (alertId: string, newMemberId: string) => {
    dispatch(reassignSLAAlert({ alertId, newMemberId }));
  };

  const handleKeepAssignment = (alertId: string) => {
    console.log('Keeping assignment for:', alertId);
    // In a real app, you might want to dismiss the alert or mark it as acknowledged
  };

  // Handlers for approvals
  const handleApprove = (approvalId: string) => {
    dispatch(approveTask(approvalId));
  };

  const handleReject = (approvalId: string) => {
    dispatch(rejectTask(approvalId));
  };

  const handleClose = (approvalId: string) => {
    // TODO: Implement close task API call
    console.log('Closing approval:', approvalId);
  };

  const handleReopen = (approvalId: string) => {
    // TODO: Implement reopen task API call
    console.log('Reopening approval:', approvalId);
  };

  const handleProcessAllSLA = () => {
    alert.confirm(
      `Bạn có chắc chắn muốn xử lý tất cả ${slaBreachAlerts.length} cảnh báo SLA?`,
      () => {
        // TODO: Implement batch processing
        console.log('Processing all SLA alerts');
      }
    );
  };

  return (
    <div className={styles.dashboard}>
      {/* Header with title */}
      <div className={styles.header}>
        <div className={styles.titleSection}>
          <h1 className={styles.pageTitle}>
            <i className="fas fa-user-tie" /> Bảng Điều Khiển Quản Lý
          </h1>
          <div className={styles.breadcrumb}>
            <span>Tổng quan / Hiệu suất nhóm</span>
          </div>
        </div>
      </div>

      {/* Stats Cards */}
      <div className={styles.statsGrid}>
        <StatCard
          icon="fas fa-clipboard-list"
          iconVariant="primary"
          label="Tổng Phiếu Yêu Cầu Đang Xử Lý"
          value={stats?.totalActiveTickets ?? 0}
          change={{
            text: stats?.change.tickets.text ?? '',
            positive: stats?.change.tickets.positive ?? true,
          }}
        />
        <StatCard
          icon="fas fa-percentage"
          iconVariant="success"
          label="SLA Compliance"
          value={
            stats?.slaComplianceRate
              ? `${stats.slaComplianceRate.toFixed(1)}%`
              : '0%'
          }
          change={{
            text: stats?.change.sla.text ?? '',
            positive: stats?.change.sla.positive ?? true,
          }}
        />
        <StatCard
          icon="fas fa-clock"
          iconVariant="warning"
          label="Thời Gian Xử Lý TB"
          value={
            stats?.averageResponseTime
              ? `${stats.averageResponseTime.toFixed(1)}h`
              : '0h'
          }
          change={{
            text: stats?.change.responseTime.text ?? '',
            positive: stats?.change.responseTime.positive ?? true,
          }}
        />
        <StatCard
          icon="fas fa-exclamation-circle"
          iconVariant="danger"
          label="Cảnh Báo & Vi Phạm SLA"
          value={stats?.slaWarningCount ?? 0}
          change={{ text: 'Cần xử lý ngay', positive: false }}
        />
      </div>

      {/* SLA Breach Alerts */}
      {slaBreachAlerts.length > 0 && (
        <div className={styles.slaSection}>
          <div className={styles.slaCard}>
            <div className={styles.slaCardHeader}>
              <h3 className={styles.slaTitle}>
                <i className="fas fa-exclamation-triangle" /> Cảnh Báo Vi Phạm
                SLA ({slaBreachAlerts.length})
              </h3>
              <div className={styles.slaHeaderActions}>
                <span className={styles.lastUpdate}>
                  <i className="fas fa-clock" /> Cập nhật: 2 phút trước
                </span>
                <button
                  className={styles.processSLAButton}
                  onClick={handleProcessAllSLA}
                >
                  <i className="fas fa-bell" /> Xử lý tất cả
                </button>
              </div>
            </div>
            <div className={styles.slaCardBody}>
              <SLABreachAlerts
                alerts={slaBreachAlerts}
                onReassign={handleReassign}
                onKeep={handleKeepAssignment}
              />
            </div>
          </div>
        </div>
      )}

      {/* Team Workload & Pending Approvals */}
      <div className={styles.mainGrid}>
        {/* Team Workload */}
        <div className={styles.teamWorkloadSection}>
          <div className={styles.card}>
            <div className={styles.cardHeader}>
              <h3 className={styles.cardTitle}>
                <i className="fas fa-users" /> Phân Bổ Công Việc Nhóm
              </h3>
              <select className={styles.periodSelect}>
                <option>Tuần này</option>
                <option>Tháng này</option>
                <option>Tùy chỉnh</option>
              </select>
            </div>
            <div className={styles.cardBody}>
              <TeamWorkload teamMembers={teamWorkload} />
            </div>
          </div>
        </div>

        {/* Pending Approvals */}
        <div className={styles.approvalsSection}>
          <div className={styles.card}>
            <div className={styles.cardHeader}>
              <h3 className={styles.cardTitle}>
                <i className="fas fa-check-double" /> Phê Duyệt (
                {pendingApprovals.length})
              </h3>
            </div>
            <div className={styles.cardBody}>
              <PendingApprovals
                approvals={pendingApprovals}
                maxItems={5}
                onApprove={handleApprove}
                onReject={handleReject}
                onClose={handleClose}
                onReopen={handleReopen}
              />
            </div>
            {pendingApprovals.length > 5 && (
              <div className={styles.cardFooter}>
                <a href="#" className={styles.viewAllLink}>
                  Xem tất cả {pendingApprovals.length} items{' '}
                  <i className="fas fa-arrow-right" />
                </a>
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Performance Charts */}
      {priorityDistribution && (
        <PerformanceCharts
          performanceTrend={performanceTrend}
          priorityDistribution={priorityDistribution}
        />
      )}

      {/* Loading indicator */}
      {loading && (
        <div className={styles.loadingOverlay}>
          <div className={styles.spinner}>
            <i className="fas fa-spinner fa-spin" />
            <span>Đang tải...</span>
          </div>
        </div>
      )}
    </div>
  );
};

export default DashboardManagerPage;
